package com.smarthub.plus;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import android.util.AtomicFile;
import org.json.*;
import org.xml.sax.*;
import org.xml.sax.helpers.DefaultHandler;
import javax.xml.parsers.SAXParserFactory;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.zip.GZIPInputStream;

/** A satellite schedule cache. It contains no IPTV URLs and never edits receiver channels. */
public final class SatelliteGuideRepository {
    private static final Object LOCK=new Object();
    private static final String FORMAT="SmartHubSatelliteGuide";
    private final Context context;
    private final File file;
    private List<Event> observed=new ArrayList<>(),xmlEvents=new ArrayList<>(),watched=new ArrayList<>();
    private Map<String,List<String>> aliases=new LinkedHashMap<>();
    private long loadedModified=-1,loadedLength=-1,importedAt;
    private String importedSource="";
    public SatelliteGuideRepository(Context context){this.context=context.getApplicationContext();file=new File(context.getFilesDir(),"satellite_guide.json");synchronized(LOCK){load();}}
    public static final class Event{
        public String id="",channelId="",channelName="",xmlId="",title="",description="",category="",source="",image="";
        public long startMs,endMs,observedAt;public boolean repeat;
        public Event copy(){Event e=new Event();e.id=id;e.channelId=channelId;e.channelName=channelName;e.xmlId=xmlId;e.title=title;e.description=description;e.category=category;e.image=image;e.source=source;e.startMs=startMs;e.endMs=endMs;e.observedAt=observedAt;e.repeat=repeat;return e;}
    }
    /** Only freshly observed, explicitly timed events enter the schedule. Unknown is not live. */
    public static List<Event> observedEvents(SatelliteState state,long now){
        List<Event> result=new ArrayList<>();if(state==null||empty(state.channelId)||state.observedAt<=0||state.observedAt>now+60_000||now-state.observedAt>120_000)return result;
        if(valid(state.title,state.startMs,state.endMs)&&state.startMs<=now&&state.endMs>now)result.add(fromObserved(state,state.title,state.startMs,state.endMs));
        if(valid(state.nextTitle,state.nextStartMs,state.nextEndMs)&&state.nextStartMs>=now&&state.nextEndMs>now)result.add(fromObserved(state,state.nextTitle,state.nextStartMs,state.nextEndMs));return result;
    }
    private static Event fromObserved(SatelliteState state,String title,long start,long end){Event e=new Event();e.channelId=state.channelId;e.channelName=state.channelName;e.title=title;e.startMs=start;e.endMs=end;e.observedAt=state.observedAt;e.image=title.equals(state.title)?state.image:state.nextImage;e.source=empty(state.source)?"Observed receiver EPG":state.source;e.id=identity("native:"+e.channelId,start);return e;}
    public void record(SatelliteState state){synchronized(LOCK){load();List<Event> incoming=observedEvents(state,System.currentTimeMillis());if(incoming.isEmpty())return;boolean changed=false;Map<String,Event> merged=index(observed);for(Event e:incoming){Event old=merged.get(e.id);if(old==null||!old.title.equals(e.title)||old.endMs!=e.endMs||!old.channelName.equals(e.channelName)){merged.put(e.id,e);changed=true;}}if(!changed)return;long oldest=System.currentTimeMillis()-7*86400000L;List<Event> next=new ArrayList<>();for(Event e:merged.values())if(e.endMs>oldest)next.add(e);next.sort(Comparator.comparingLong(e->e.startMs));if(next.size()>2000)next=new ArrayList<>(next.subList(next.size()-2000,next.size()));observed=next;try{save();}catch(IOException e){context.getSharedPreferences("smarthub",0).edit().putString("satellite_guide_error",e.getMessage()).apply();}}}
    public void importXml(String xml,String source)throws Exception{
        List<PlaylistRepository.Programme> parsed=PlaylistRepository.parseXmlTv(xml);if(parsed.isEmpty())throw new IOException("XMLTV contains no valid timed programmes");Map<String,List<String>> names=parseAliases(xml);List<Event> events=new ArrayList<>();
        for(PlaylistRepository.Programme p:parsed){Event e=new Event();e.xmlId=p.channelId;e.channelName=display(names,p.channelId);e.title=p.title;e.description=p.description;e.image=p.image;e.category=p.category;e.startMs=p.startMs;e.endMs=p.endMs;e.repeat=p.repeat;e.source=source;e.id=identity("xml:"+e.xmlId,e.startMs);events.add(e);}events=mergeEvents(Collections.emptyList(),events);
        synchronized(LOCK){load();List<Event> previousEvents=xmlEvents;Map<String,List<String>> previousAliases=aliases;String previousSource=importedSource;long previousAt=importedAt;xmlEvents=events;aliases=names;importedSource=source;importedAt=System.currentTimeMillis();try{save();}catch(Exception e){xmlEvents=previousEvents;aliases=previousAliases;importedSource=previousSource;importedAt=previousAt;throw e;}}
    }
    public static Map<String,List<String>> parseAliases(String xml)throws Exception{
        if(xml==null||xml.length()>PlaylistRepository.MAX_BYTES)throw new IOException("XMLTV exceeds limit");String upper=xml.toUpperCase(Locale.ROOT);if(upper.contains("<!DOCTYPE")||upper.contains("<!ENTITY"))throw new IOException("DTD and entities are forbidden");
        Map<String,List<String>> result=new LinkedHashMap<>();SAXParserFactory factory=SAXParserFactory.newInstance();factory.setValidating(false);factory.setNamespaceAware(false);try{factory.setFeature("http://xml.org/sax/features/external-general-entities",false);factory.setFeature("http://xml.org/sax/features/external-parameter-entities",false);factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd",false);}catch(Exception ignored){}
        XMLReader reader=factory.newSAXParser().getXMLReader();reader.setEntityResolver((publicId,systemId)->new InputSource(new StringReader("")));reader.setContentHandler(new DefaultHandler(){String channel;StringBuilder text=new StringBuilder();boolean reading;int depth;
            @Override public void startElement(String uri,String local,String q,Attributes a)throws SAXException{if(++depth>64)throw new SAXException("XML nesting limit");if(depth==1&&!q.equals("tv"))throw new SAXException("Expected XMLTV root");if(q.equals("channel")){if(result.size()>=10000)throw new SAXException("Too many channels");channel=a.getValue("id");if(channel!=null&&!channel.isEmpty())result.computeIfAbsent(channel,k->new ArrayList<>());}if(q.equals("display-name")&&channel!=null){reading=true;text.setLength(0);}}
            @Override public void characters(char[] c,int offset,int length)throws SAXException{if(reading){if(text.length()+length>1000)throw new SAXException("Channel name limit");text.append(c,offset,length);}}
            @Override public void endElement(String uri,String local,String q){if(q.equals("display-name")&&reading){String name=text.toString().trim();List<String> values=result.get(channel);if(values!=null&&!name.isEmpty()&&values.size()<20&&!values.contains(name))values.add(name);reading=false;}if(q.equals("channel"))channel=null;depth--;}});reader.parse(new InputSource(new StringReader(xml)));return result;
    }
    /** Exact aliases only; ambiguous display names require an explicit user mapping. */
    public static String resolveXmlId(SatelliteState state,String explicit,Map<String,List<String>> aliases){
        if(!empty(explicit))return explicit;if(state==null)return "";if(aliases.containsKey(state.channelId))return state.channelId;String wanted=PlaylistRepository.normalize(state.channelName);if(wanted.isEmpty())return "";String found="";
        for(Map.Entry<String,List<String>> item:aliases.entrySet()){boolean match=PlaylistRepository.normalize(item.getKey()).equals(wanted);for(String name:item.getValue())if(PlaylistRepository.normalize(name).equals(wanted))match=true;if(match){if(!found.isEmpty()&&!found.equals(item.getKey()))return "";found=item.getKey();}}return found;
    }
    /** Timed, physical-service matches only; reads cached observations once for a whole list. */
    Map<String,Event> currentChannels(Set<String> channelIds,long now){synchronized(LOCK){load();Map<String,Event> result=new HashMap<>();for(Event e:observed)if(channelIds.contains(e.channelId)&&valid(e.title,e.startMs,e.endMs)&&e.startMs<=now&&e.endMs>now){Event old=result.get(e.channelId);if(old==null||e.startMs>old.startMs)result.put(e.channelId,e.copy());}return result;}}
    public PlaylistRepository.Programme currentFor(SatelliteState state,long now){synchronized(LOCK){load();if(state==null||empty(state.channelId))return null;String selected=resolveXmlId(state,context.getSharedPreferences("smarthub",0).getString("satellite_xmltv_id:"+state.channelId,""),allAliases());Event current=current(xmlEvents,selected,now);if(current==null)return null;PlaylistRepository.Programme p=new PlaylistRepository.Programme();p.channelId=current.xmlId;p.title=current.title;p.description=current.description;p.image=current.image;p.category=current.category;p.startMs=current.startMs;p.endMs=current.endMs;p.repeat=current.repeat;return p;}}
    public static Event current(List<Event> events,String xmlId,long now){if(empty(xmlId))return null;Event found=null;for(Event e:events)if(xmlId.equals(e.xmlId)&&valid(e.title,e.startMs,e.endMs)&&e.startMs<=now&&e.endMs>now&&(found==null||e.startMs>found.startMs))found=e;return found==null?null:found.copy();}
    public PlaylistRepository.Programme nextFor(SatelliteState state,long now){synchronized(LOCK){load();if(state==null||empty(state.channelId))return null;String id=resolveXmlId(state,context.getSharedPreferences("smarthub",0).getString("satellite_xmltv_id:"+state.channelId,""),allAliases());if(id.isEmpty())return null;Event next=null;for(Event e:xmlEvents)if(e.xmlId.equals(id)&&e.startMs>now&&(next==null||e.startMs<next.startMs))next=e;if(next==null)return null;PlaylistRepository.Programme p=new PlaylistRepository.Programme();p.channelId=next.xmlId;p.title=next.title;p.description=next.description;p.image=next.image;p.startMs=next.startMs;p.endMs=next.endMs;return p;}}
    public void map(String nativeId,String xmlId)throws IOException{synchronized(LOCK){load();if(empty(nativeId))throw new IOException("No observed native channel to map");if(!empty(xmlId)&&!allAliases().containsKey(xmlId))throw new IOException("Unknown XMLTV channel ID");SharedPreferences.Editor editor=context.getSharedPreferences("smarthub",0).edit();if(empty(xmlId))editor.remove("satellite_xmltv_id:"+nativeId);else editor.putString("satellite_xmltv_id:"+nativeId,xmlId);editor.apply();}}
    public Map<String,List<String>> channelAliases(){synchronized(LOCK){load();return allAliases();}}
    private Map<String,List<String>> allAliases(){Map<String,List<String>> copy=new LinkedHashMap<>();for(Map.Entry<String,List<String>> item:aliases.entrySet())copy.put(item.getKey(),new ArrayList<>(item.getValue()));for(Event e:xmlEvents)copy.computeIfAbsent(e.xmlId,k->new ArrayList<>());return copy;}
    public List<Event> search(String query,long now,boolean includePast){synchronized(LOCK){load();List<Event> all=new ArrayList<>(xmlEvents);all.addAll(observed);SatelliteState state=SatelliteState.read(context);String mapped=resolveXmlId(state,context.getSharedPreferences("smarthub",0).getString("satellite_xmltv_id:"+state.channelId,""),allAliases());List<Event> output=new ArrayList<>();for(Event raw:all){Event e=raw.copy();if(e.xmlId.equals(mapped)&&!mapped.isEmpty()){e.channelId=state.channelId;if(!empty(state.channelName))e.channelName=state.channelName;}if(matches(e,query,now,includePast))output.add(e);}output.sort(Comparator.comparingLong(e->e.startMs));return output;}}
    public static boolean matches(Event e,String query,long now,boolean includePast){if(e==null||!valid(e.title,e.startMs,e.endMs)||!includePast&&e.endMs<=now)return false;String time=DateTimeFormatter.ofPattern("HH:mm dd/MM/yyyy").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(e.startMs));String value=e.title+" "+e.channelName+" "+e.xmlId+" "+e.category+" "+e.description+" "+time+(e.repeat?" repeat replay إعادة اعادة":"");return PlaylistRepository.matches(value,query);}
    public static List<Event> mergeEvents(List<Event> previous,List<Event> added){Map<String,Event> result=index(previous);for(Event e:added)if(valid(e.title,e.startMs,e.endMs))result.put(e.id,e.copy());List<Event> out=new ArrayList<>(result.values());out.sort(Comparator.comparingLong(e->e.startMs));return out;}
    public String sourceSummary(){synchronized(LOCK){load();return "XMLTV: "+xmlEvents.size()+" · "+importedSource+(importedAt>0?" · "+DateTimeFormatter.ofPattern("dd/MM HH:mm").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(importedAt)):"")+"\nObserved receiver events: "+observed.size()+" · Watched: "+watched.size();}}
    public List<Event> watchlist(){synchronized(LOCK){load();List<Event> result=new ArrayList<>();for(Event e:watched)result.add(e.copy());return result;}}
    public void watch(Event value)throws IOException{synchronized(LOCK){load();if(value==null||!valid(value.title,value.startMs,value.endMs)||value.endMs<=System.currentTimeMillis())throw new IOException("Only future or ongoing timed events can be watched");Map<String,Event> next=index(watched);if(next.size()>=200&&!next.containsKey(value.id))throw new IOException("Watchlist limit: 200");next.put(value.id,value.copy());List<Event> before=watched;watched=new ArrayList<>(next.values());try{save();}catch(IOException e){watched=before;throw e;}schedule(value);}}
    public void unwatch(String id)throws IOException{synchronized(LOCK){load();Event removed=null;for(Event e:watched)if(e.id.equals(id))removed=e;List<Event> before=watched;watched=new ArrayList<>(watched);watched.removeIf(e->e.id.equals(id));try{save();}catch(IOException e){watched=before;throw e;}if(removed!=null){cancelAlarm(removed,"start");cancelAlarm(removed,"end");}}}
    public void reschedule(){for(Event e:watchlist())schedule(e);}
    private void schedule(Event e){AlarmManager alarms=(AlarmManager)context.getSystemService(Context.ALARM_SERVICE);long now=System.currentTimeMillis();for(String kind:new String[]{"start","end"}){long at=kind.equals("start")?e.startMs:e.endMs;if(at<=now)continue;PendingIntent pending=pending(e,kind,at);try{if(Build.VERSION.SDK_INT<31||alarms.canScheduleExactAlarms())alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);else alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);}catch(SecurityException error){alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);}}}
    private PendingIntent pending(Event e,String kind,long at){Intent intent=new Intent(context,EventReminderReceiver.class).setAction(EventReminderReceiver.ACTION).setData(Uri.parse("smarthub://event/"+e.id+"/"+kind)).putExtra("event_id",e.id).putExtra("kind",kind).putExtra("event_at",at);return PendingIntent.getBroadcast(context,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private void cancelAlarm(Event e,String kind){((AlarmManager)context.getSystemService(Context.ALARM_SERVICE)).cancel(pending(e,kind,kind.equals("start")?e.startMs:e.endMs));}
    public static boolean reminderDue(Event e,String kind,long at,long now){if(e==null||!valid(e.title,e.startMs,e.endMs)||!kind.equals("start")&&!kind.equals("end"))return false;long expected=kind.equals("start")?e.startMs:e.endMs;return at==expected&&now>=expected-1000&&now<=expected+10*60_000L&&(!kind.equals("start")||now<e.endMs);}
    public static String fetchXml(String address)throws Exception{URI uri=new URI(address.trim());if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IOException("XMLTV URL must use HTTPS without embedded credentials");for(int redirects=0;redirects<4;redirects++){HttpURLConnection connection=(HttpURLConnection)uri.toURL().openConnection();try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(7000);connection.setReadTimeout(15000);connection.setRequestProperty("User-Agent","SmartHubPlus/1.0");connection.setRequestProperty("Accept-Encoding","gzip");int code=connection.getResponseCode();if(code>=300&&code<400){String location=connection.getHeaderField("Location");if(location==null)throw new IOException("Missing XMLTV redirect");URI next=uri.resolve(location);if(!"https".equalsIgnoreCase(next.getScheme())||!Objects.equals(uri.getHost(),next.getHost())||uri.getPort()!=next.getPort()||next.getUserInfo()!=null)throw new IOException("Cross-host XMLTV redirect refused");uri=next;continue;}if(code<200||code>=300)throw new IOException("XMLTV HTTP "+code);try(InputStream raw=connection.getInputStream();InputStream in="gzip".equalsIgnoreCase(connection.getHeaderField("Content-Encoding"))||uri.getPath().endsWith(".gz")?new GZIPInputStream(raw):raw){return PlaylistRepository.readBounded(in);}}finally{connection.disconnect();}}throw new IOException("Too many XMLTV redirects");}
    private void load(){long modified=file.lastModified(),length=file.length();if(modified==loadedModified&&length==loadedLength)return;try{if(!file.isFile())return;JSONObject root;try(InputStream in=new FileInputStream(file)){root=new JSONObject(PlaylistRepository.readBounded(in));}if(!FORMAT.equals(root.optString("format"))||root.optInt("version")!=1)return;observed=decode(root.optJSONArray("observed"),2000);xmlEvents=decode(root.optJSONArray("xmltv"),30000);watched=decode(root.optJSONArray("watched"),200);Map<String,List<String>> names=new LinkedHashMap<>();JSONObject stored=root.optJSONObject("aliases");if(stored!=null){Iterator<String> keys=stored.keys();while(keys.hasNext()&&names.size()<10000){String key=keys.next();JSONArray values=stored.optJSONArray(key);List<String> list=new ArrayList<>();if(values!=null)for(int i=0;i<Math.min(20,values.length());i++)list.add(values.optString(i));names.put(key,list);}}aliases=names;importedAt=root.optLong("importedAt",0);importedSource=root.optString("source","");}catch(Exception ignored){}finally{loadedModified=modified;loadedLength=length;}}
    private void save()throws IOException{AtomicFile atomic=new AtomicFile(file);FileOutputStream out=null;try{JSONObject names=new JSONObject();for(Map.Entry<String,List<String>> item:aliases.entrySet())names.put(item.getKey(),new JSONArray(item.getValue()));JSONObject root=new JSONObject().put("format",FORMAT).put("version",1).put("observed",encode(observed)).put("xmltv",encode(xmlEvents)).put("watched",encode(watched)).put("aliases",names).put("source",importedSource).put("importedAt",importedAt);byte[] bytes=root.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>PlaylistRepository.MAX_BYTES)throw new IOException("Guide cache exceeds 24 MB");out=atomic.startWrite();out.write(bytes);atomic.finishWrite(out);loadedModified=file.lastModified();loadedLength=file.length();}catch(Exception e){if(out!=null)atomic.failWrite(out);throw new IOException("Could not save satellite guide",e);}}
    private static JSONArray encode(List<Event> events)throws Exception{JSONArray result=new JSONArray();for(Event e:events)result.put(new JSONObject().put("id",e.id).put("channelId",e.channelId).put("channelName",e.channelName).put("xmlId",e.xmlId).put("title",e.title).put("description",e.description).put("image",e.image).put("category",e.category).put("source",e.source).put("start",e.startMs).put("end",e.endMs).put("observedAt",e.observedAt).put("repeat",e.repeat));return result;}
    private static List<Event> decode(JSONArray rows,int max){List<Event> result=new ArrayList<>();if(rows==null)return result;for(int i=0;i<Math.min(max,rows.length());i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;Event e=new Event();e.id=row.optString("id","");e.channelId=row.optString("channelId","");e.channelName=row.optString("channelName","");e.xmlId=row.optString("xmlId","");e.title=row.optString("title","");e.description=row.optString("description","");e.image=PlaylistRepository.epgImage(row.optString("image"));e.category=row.optString("category","");e.source=row.optString("source","");e.startMs=row.optLong("start",0);e.endMs=row.optLong("end",0);e.observedAt=row.optLong("observedAt",0);e.repeat=row.optBoolean("repeat",false);if(!empty(e.id)&&valid(e.title,e.startMs,e.endMs))result.add(e);}return result;}
    private static String display(Map<String,List<String>> aliases,String id){List<String> names=aliases.get(id);return names==null||names.isEmpty()?id:names.get(0);}
    private static Map<String,Event> index(List<Event> list){Map<String,Event> result=new LinkedHashMap<>();for(Event e:list)if(e!=null&&!empty(e.id)&&valid(e.title,e.startMs,e.endMs))result.put(e.id,e.copy());return result;}
    private static boolean valid(String title,long start,long end){return !empty(title)&&start>0&&end>start;}
    private static boolean empty(String value){return value==null||value.trim().isEmpty();}
    private static String identity(String channel,long at){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest((channel+"|"+at).getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
}
